  "claims": [
    {
      "claim": "The query is a permanently charged quaternary ammonium tropane ester; diphemanil methylsulphate, also a quaternary ammonium salt, showed very low oral bioavailability in healthy subjects after a 250 mg oral dose (minimal urinary recovery), providing direct low-F evidence for this charge class.",
      "card_ids": ["C05"]
    },
    {
      "claim": "Strongly cationic molecules can have F well below 20%: DX-9065 had human oral bioavailability of 2–3% (2.8±1.5% for a conventional gelatin capsule; 3% for a fasted conventional capsule), attributed to its strong basic amidino groups.",
      "card_ids": ["C01", "C03", "C12"]
    },
    {
      "claim": "L3 oral exposure records for quaternary ammonium antimuscarinics trospium and glycopyrrolate show only pg/mL plasma Cmax after milligram oral doses (trospium 60 mg XR Cmax 1517–1873 pg/mL; glycopyrrolate 2 mg Cmax 318 pg/mL), consistent with poor oral absorption and low F.",
      "card_ids": ["C28", "C34", "C35", "C38"]
    },
    {
      "claim": "The remaining L3 records (dolasetron/hydrodolasetron and dexmethylphenidate) are not applicable to the query because they are tertiary amines rather than quaternary ammonium compounds and do not provide threshold-relevant evidence for this molecule.",
      "card_ids": ["C29", "C30", "C31", "C32", "C33", "C36", "C37", "C39"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C28", "C34", "C35", "C38"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "No matched oral versus intravenous exposure data are available for the query.",
    "L3 records provide Cmax/Tmax/AUC but not absolute F for trospium/glycopyrrolate; the low-F inference relies on structural class and direct low-F analogs.",
    "Differences in tropane/epoxide ester structure, metabolism, and formulation between the query and the cited analogs are unmeasured.",
    "No direct data on intestinal permeability, efflux transport, or first-pass metabolism for the query are provided.",
    "Dolasetron/hydrodolasetron and dexmethylphenidate L3 records are not applicable due to different charge and structural class."
  ],
  "decision_summary": "Predicted low: the query is a permanently charged quaternary ammonium tropane ester. Direct low-F evidence for the quaternary ammonium class (diphemanil, C05) and strongly cationic molecules (DX-9065, C01/C03/C12) supports F<20%. New L3 oral exposure records for quaternary ammonium antimuscarinics trospium and glycopyrrolate (C28/C34/C35/C38) show only pg/mL plasma Cmax after milligram oral doses, consistent with poor absorption and low F; dolasetron and dexmethylphenidate records are not applicable. Confidence remains moderate because no direct query F measurement exists."
}

